{
  "definition_simple": "商品や部品などが保管されていること",
  "definition_standard": "企業や店舗などで、販売や生産に備えて保管されている商品や原材料の数量。在庫管理の対象となる",
  "pos": "名詞",
  "semantic_class": "abstract",
  "sentences": [
    {
      "text": "店に在庫があります。",
      "tier": "T1"
    },
    {
      "text": "在庫を確認してください。",
      "tier": "T1"
    },
    {
      "text": "在庫が少なくなってきたので、発注します。",
      "tier": "T2"
    },
    {
      "text": "在庫管理システムを導入しました。",
      "tier": "T2"
    },
    {
      "text": "この商品は在庫切れです。",
      "tier": "T3"
    },
    {
      "text": "在庫を適正水準に維持する必要があります。",
      "tier": "T3"
    },
    {
      "text": "在庫回転率が低いとキャッシュフローに悪影響を及ぼす。",
      "tier": "T4"
    },
    {
      "text": "在庫評価方法には先入先出法と後入先出法がある。",
      "tier": "T5"
    },
    {
      "text": "需要予測に基づいた在庫補充計画を策定しなければならない。",
      "tier": "T5"
    },
    {
      "text": "在庫の過剰在庫は保管コストを増大させるため、JIT（ジャストインタイム）方式の採用が検討された。",
      "tier": "T6"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "primary_collocate": "管理",
  "collocation_distractors": [
    {
      "word": "倉庫",
      "reason": "「倉庫」は在庫を保管する場所であり、在庫そのものと直接的な共起関係ではないため、正しいコロケーションではない"
    },
    {
      "word": "商品",
      "reason": "「商品」は在庫の具体的内容を指すが、通常「在庫を商品する」とは言わず、「在庫管理」のような固定表現とはならない"
    },
    {
      "word": "販売",
      "reason": "「販売」は在庫の行動ではなく、在庫を販売するという意味では共起するが、最も自然な固定コロケーションとは言えない"
    }
  ],
  "collocation_wrong_collocate": "作る",
  "cloze_sentence": "当店では、＿＿＿を十分に確保しております。",
  "cloze_distractors": [
    {
      "word": "在庫品",
      "reason": "「在庫品」は「在庫」と意味が近いが、通常「在庫を確保」とは言わず「在庫品を確保」は不自然（使用場面が異なる）"
    },
    {
      "word": "在庫管理",
      "reason": "「在庫管理」は名詞で「管理」という動作を含むため、「を確保」の目的語としては適合しない（動詞「管理」が必要）"
    },
    {
      "word": "在庫切れ",
      "reason": "「在庫切れ」は「在庫がない状態」を意味するため、文意（十分に確保）と矛盾する"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "在庫が美味しい。",
      "reason": "「美味しい」は味覚形容詞であり、在庫に対して用いることは意味的に不可能（選択制限違反）"
    },
    {
      "sentence": "彼は在庫を食べた。",
      "reason": "「食べる」の対象は通常食品であり、在庫（概念／数量）を食べることはできない（語彙選択の誤り）"
    },
    {
      "sentence": "在庫が走る。",
      "reason": "「走る」は物理的な移動動作を表す動詞で、在庫のような非生物・抽象物に対して使うと文法的に許容されるが、通常の文脈では意味が成立せず（不適切な述語選択）"
    }
  ],
  "spot_incorrect": {
    "sentence": "在庫をが不足しています。",
    "error_description": "助詞「を」と「が」が連続して使用されており、正しい文法では「を」または「が」のいずれか一方のみを用いるべき",
    "corrected": "在庫が不足しています。"
  },
  "word_family_forms": [
    "在庫品",
    "在庫管理",
    "在庫切れ",
    "在庫高"
  ],
  "word_family_fake_forms": [
    "在庫性",
    "在庫的",
    "在庫化"
  ],
  "syn_ant_candidates": [
    {
      "word": "ストック",
      "relation": "synonym"
    },
    {
      "word": "在庫品",
      "relation": "synonym"
    },
    {
      "word": "品切れ",
      "relation": "antonym"
    },
    {
      "word": "欠品",
      "relation": "antonym"
    }
  ],
  "particle_sentence": "在庫（___）あります。",
  "particle_candidates": [
    {
      "particle": "が",
      "correct": true,
      "reason": "存在文の主語を表すには「が」が正しく、「在庫があります」が自然な文となる"
    },
    {
      "particle": "を",
      "correct": false,
      "reason": "「を」は他動詞の目的語に用いるが、「あります」は自動詞であり、「を」を使うと不適切"
    },
    {
      "particle": "は",
      "correct": false,
      "reason": "「は」は主題を示すが、この文では単に存在を述べるため「が」が優先され、「は」を使うと対比のニュアンスが生じ不自然"
    },
    {
      "particle": "に",
      "correct": false,
      "reason": "「に」は場所や時間を示すが、「在庫」が存在の主体であるため、位置を表す「に」は使えない"
    }
  ]
}
